out={'schema':'marici.voevodsky.CR1-D3-extraordinary-costalk-BC.v1','prospective_action':'CR1A1a1i1a1a2i1a1a2b1a1a1_construct_D3_extraordinary_costalk_BC','outcome_contract':{'++':'a marked spatial multi-Rees pull-push induces 1-r on the full H0/Tor1 costalk and the nonzero Tate roof','+-':'the finite cube and unique Tate carrier are fixed, but the spatial multi-Rees exterior BC map remains absent','-+':'the costalk carrier or Tate comparison is obstructed','--':'three-normal endpoint data are unavailable'},'resolution':'+-','finite_cube':{'states_per_endpoint':8,'Tor_copies':2,'top_boundary':[1,-1,1],'d_squared':0,'D3_and_reflection':True},'Tate_candidate':{'ranks':[1,3,3,1],'middle':'1-r','middle_Smith':[1,1,0],'augmentation_qSigma':3,'index':3,'all_H0_Tor1_retained':True},'negative_control':'A common Rees parameter creates unwanted t-torsion. Three separately labelled t_i are mandatory.','remaining':'Construct a marked spatial multi-Rees correspondence inducing lambda_ex with associated grade 1-r and the same nonzero Tate two-extension.','refinement':['CR1A1a1i1a1a2i1a1a2b1a1a1a_construct_marked_spatial_multi_Rees_correspondence'],'next':'Build the spatial multi-Rees pull-push while retaining every t_i conormal line.','checks':checks,'passed':True};p=ROOT/'research/voevodsky/results/CR1_D3_extraordinary_costalk_BC.json';p.write_text(json.dumps(out,indent=2)+'\n');print(json.dumps({'passed':True,'resolution':'+-','Tate_index':3,'spatial_map':False,'next':out['refinement'][0]}))
